import type { Attribute, Html } from "foldkit/html";
import { html } from "foldkit/html";

import {
  commandEmptyClassName,
  commandGroupClassName,
  commandInputClassName,
  commandInputWrapperClassName,
  commandItemClassName,
  commandListClassName,
  commandRootClassName,
  commandSeparatorClassName,
  commandShortcutClassName,
} from "./view";

export {
  commandEmptyClassName,
  commandGroupClassName,
  commandInputClassName,
  commandInputWrapperClassName,
  commandItemClassName,
  commandListClassName,
  commandRootClassName,
  commandSeparatorClassName,
  commandShortcutClassName,
} from "./view";

export type CommandItem = Readonly<{
  label: string;
  group: string;
  shortcut?: string;
  disabled?: boolean;
}>;

type ViewConfig<ParentMessage> = Readonly<{
  children: readonly (Html | string)[];
  className?: string;
  attributes?: readonly Attribute<ParentMessage>[];
}>;

export type InputViewConfig<ParentMessage> = Readonly<{
  value: string;
  onInput: (value: string) => ParentMessage;
  placeholder?: string;
  ariaLabel?: string;
  listId?: string;
  className?: string;
  attributes?: readonly Attribute<ParentMessage>[];
}>;

export type ItemViewConfig<ParentMessage> = Readonly<{
  item: CommandItem;
  onSelect?: ParentMessage;
  selected?: boolean;
  className?: string;
  attributes?: readonly Attribute<ParentMessage>[];
}>;

export const defaultItems: readonly CommandItem[] = [
  { group: "Suggestions", label: "Calendar" },
  { group: "Suggestions", label: "Search Emoji" },
  { group: "Suggestions", label: "Calculator" },
  { group: "Settings", label: "Profile", shortcut: "⌘P" },
  { group: "Settings", label: "Billing", shortcut: "⌘B" },
  { group: "Settings", label: "Settings", shortcut: "⌘S" },
];

const classNames = (...values: readonly (string | undefined)[]): string =>
  values
    .filter((value): value is string => value !== undefined && value !== "")
    .join(" ");

export const filterItems = (
  items: readonly CommandItem[],
  query: string
): readonly CommandItem[] => {
  const needle = query.trim().toLowerCase();

  if (needle === "") {
    return items;
  }

  return items.filter(
    (item) =>
      item.label.toLowerCase().includes(needle) ||
      item.group.toLowerCase().includes(needle)
  );
};

export const rootView = <ParentMessage>({
  children,
  className,
  attributes = [],
}: ViewConfig<ParentMessage>): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      h.DataAttribute("slot", "command"),
      h.Class(classNames(commandRootClassName, className)),
      ...attributes,
    ],
    children
  );
};

export const inputView = <ParentMessage>({
  value,
  onInput,
  placeholder = "Type a command or search...",
  ariaLabel = "Command search",
  listId,
  className,
  attributes = [],
}: InputViewConfig<ParentMessage>): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      h.DataAttribute("slot", "command-input-wrapper"),
      h.Class(commandInputWrapperClassName),
    ],
    [
      h.input([
        h.DataAttribute("slot", "command-input"),
        h.Type("text"),
        h.Value(value),
        h.OnInput(onInput),
        h.AriaLabel(ariaLabel),
        h.Attribute("role", "combobox"),
        ...(listId === undefined
          ? []
          : [
              h.Attribute("aria-controls", listId),
              h.Attribute("aria-expanded", "true"),
            ]),
        h.Placeholder(placeholder),
        h.Class(classNames(commandInputClassName, className)),
        ...attributes,
      ]),
    ]
  );
};

export const listView = <ParentMessage>({
  children,
  className,
  attributes = [],
}: ViewConfig<ParentMessage>): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      h.DataAttribute("slot", "command-list"),
      h.Attribute("role", "listbox"),
      h.Class(classNames(commandListClassName, className)),
      ...attributes,
    ],
    children
  );
};

export const emptyView = <ParentMessage>({
  children,
  className,
  attributes = [],
}: ViewConfig<ParentMessage>): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      h.DataAttribute("slot", "command-empty"),
      h.Class(classNames(commandEmptyClassName, className)),
      ...attributes,
    ],
    children
  );
};

export const groupView = <ParentMessage>({
  heading,
  children,
  className,
  attributes = [],
}: ViewConfig<ParentMessage> & Readonly<{ heading: string }>): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      h.DataAttribute("slot", "command-group"),
      h.Class(classNames(commandGroupClassName, className)),
      ...attributes,
    ],
    [
      h.div([h.DataAttribute("slot", "command-group-heading")], [heading]),
      ...children,
    ]
  );
};

export const shortcutView = <ParentMessage>(shortcut: string): Html => {
  const h = html<ParentMessage>();

  return h.span(
    [
      h.DataAttribute("slot", "command-shortcut"),
      h.Class(commandShortcutClassName),
    ],
    [shortcut]
  );
};

export const itemView = <ParentMessage>({
  item,
  onSelect,
  selected,
  className,
  attributes = [],
}: ItemViewConfig<ParentMessage>): Html => {
  const h = html<ParentMessage>();

  return h.button(
    [
      h.Type("button"),
      h.DataAttribute("slot", "command-item"),
      h.DataAttribute("selected", selected === true ? "true" : "false"),
      h.DataAttribute("disabled", item.disabled === true ? "true" : "false"),
      h.Attribute("role", "option"),
      h.Attribute("aria-selected", selected === true ? "true" : "false"),
      ...(item.disabled === true
        ? [h.Disabled(true), h.AriaDisabled(true)]
        : onSelect === undefined
          ? []
          : [h.OnClick(onSelect)]),
      h.Class(classNames(commandItemClassName, className)),
      ...attributes,
    ],
    [
      h.span([], [item.label]),
      ...(item.shortcut === undefined
        ? []
        : [shortcutView<ParentMessage>(item.shortcut)]),
    ]
  );
};

export const separatorView = <ParentMessage>(): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      h.AriaHidden(true),
      h.DataAttribute("slot", "command-separator"),
      h.Class(commandSeparatorClassName),
    ],
    []
  );
};

export const commandRootClassName =
  "flex h-full w-full flex-col overflow-hidden rounded-lg border border-gray-200 bg-white text-gray-950 shadow-sm";

export const commandInputWrapperClassName =
  "flex h-11 items-center border-b border-gray-200 px-3";

export const commandInputClassName =
  "flex h-10 w-full rounded-md bg-transparent py-3 text-sm outline-none placeholder:text-gray-500 disabled:cursor-not-allowed disabled:opacity-50";

export const commandListClassName =
  "max-h-72 overflow-y-auto overflow-x-hidden";

export const commandEmptyClassName = "py-6 text-center text-sm text-gray-500";

export const commandGroupClassName =
  "overflow-hidden p-1 text-gray-950 [&_[data-slot=command-group-heading]]:px-2 [&_[data-slot=command-group-heading]]:py-1.5 [&_[data-slot=command-group-heading]]:text-xs [&_[data-slot=command-group-heading]]:font-medium [&_[data-slot=command-group-heading]]:text-gray-500";

export const commandItemClassName =
  "relative flex cursor-pointer select-none items-center gap-2 rounded-sm px-2 py-1.5 text-sm outline-none hover:bg-gray-100 hover:text-gray-950 data-[selected=true]:bg-gray-100 data-[disabled=true]:pointer-events-none data-[disabled=true]:opacity-50";

export const commandSeparatorClassName = "-mx-1 h-px bg-gray-200";

export const commandShortcutClassName =
  "ml-auto text-xs tracking-widest text-gray-500";

import { Scene } from "foldkit";
import type { Html } from "foldkit/html";
import { describe, expect, test } from "vitest";

import * as Command from "./index";

const view = (query: string): Html =>
  Command.rootView<string>({
    children: [
      Command.inputView({
        value: query,
        onInput: (value) => value,
        listId: "command-list",
      }),
      Command.listView({
        attributes: [],
        children: Command.filterItems(Command.defaultItems, query).map((item) =>
          Command.itemView({
            item,
            selected: item.label === "Calendar",
            onSelect: item.label,
          })
        ),
      }),
    ],
  });

describe("Command registry view", () => {
  test("renders command input, list items, and shortcuts", () => {
    Scene.scene(
      {
        update: (_model: string, message: string): readonly [string, []] => [
          message,
          [],
        ],
        view,
      },
      Scene.with(""),
      Scene.expect(
        Scene.role("combobox", { name: "Command search" })
      ).toHaveAttr("placeholder", "Type a command or search..."),
      Scene.expect(Scene.role("option", { name: "Calendar" })).toHaveAttr(
        "aria-selected",
        "true"
      ),
      Scene.expect(Scene.text("⌘P")).toHaveAttr(
        "data-slot",
        "command-shortcut"
      ),
      Scene.type(Scene.role("combobox", { name: "Command search" }), "bill"),
      Scene.expect(Scene.text("Billing")).toExist(),
      Scene.expect(Scene.role("option", { name: "Calendar" })).toBeAbsent()
    );
  });

  test("filters command items by label and group", () => {
    expect(Command.filterItems(Command.defaultItems, "settings")).toHaveLength(
      3
    );
  });
});
